function Header({ currentView, setView, currentScreen, setScreen, maxClearedStep = 1, actorRole, setActorRole, currentUser: propCurrentUser, setCurrentUser: propSetCurrentUser }) {
  const [featuresOpen, setFeaturesOpen] = useState(false);
  const [authModalOpen, setAuthModalOpen] = useState(false);
  const [authTab, setAuthTab] = useState('login');
  const [localUser, setLocalUser] = useState(null);
  const currentUser = propCurrentUser !== undefined ? propCurrentUser : localUser;
  const setCurrentUser = propSetCurrentUser || setLocalUser;
  const featuresRef = useRef(null);

  useEffect(() => {
    function handleClickOutside(event) {
      if (featuresRef.current && !featuresRef.current.contains(event.target)) {
        setFeaturesOpen(false);
      }
    }
    function handleKeyDown(event) {
      if (event.key === 'Escape') {
        setFeaturesOpen(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('mousedown', handleClickOutside);
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, []);

  const allFeatureItems = [
    {
      id: 'overview',
      code: 'Module 00',
      icon: '📊',
      label: actorRole === 'patient' ? 'Patient Overview' : 'Platform Overview',
      description: actorRole === 'patient' ? 'Personal health portal, appointments, records & referral tracking' : 'Unified command hub, patient & clinical role views, system KPIs',
      onSelect: () => setView('overview')
    },
    {
      id: 'feature1',
      code: 'Module 01',
      icon: '🧭',
      label: 'Care Navigator',
      description: 'Autonomous symptom triage & emergency facility matching',
      onSelect: () => { setView('feature1'); setScreen(1); }
    },
    {
      id: 'feature2',
      code: 'Module 02',
      icon: '👨‍⚕️',
      label: 'Teleconsult & Queue',
      description: 'Multi-specialty doctor roster & priority booking',
      onSelect: () => setView('feature2')
    },
    {
      id: 'feature3',
      code: 'Module 03',
      icon: '🔄',
      label: 'Smart Referrals',
      description: 'Closed-loop digital referral passes & facility network',
      onSelect: () => setView('feature3')
    },
    {
      id: 'feature4',
      code: 'Module 04',
      icon: '📋',
      label: 'High-Risk Follow-Ups',
      description: 'Longitudinal ASHA field tracking & escalation',
      onSelect: () => setView('feature4')
    },
    {
      id: 'feature5',
      code: 'Module 05',
      icon: '📑',
      label: 'Health Records (ABDM)',
      description: 'Interoperable FHIR health records & emergency override',
      onSelect: () => setView('feature5')
    },
    {
      id: 'feature6',
      code: 'Module 06',
      icon: '💊',
      label: 'Medicine & Diagnostic Lab',
      description: 'Pharmacy inventory reservations & diagnostic tracking',
      onSelect: () => setView('feature6')
    },
    {
      id: 'feature7',
      code: 'Module 07',
      icon: '🏥',
      label: 'Facility Dashboard',
      description: 'Readiness Index, ICU beds, oxygen buffer & triage meters',
      onSelect: () => setView('feature7')
    },
    {
      id: 'feature8',
      code: 'Module 08',
      icon: '🏛️',
      label: 'Govt Health Schemes',
      description: 'RAG scheme discovery, deterministic rules engine & gap-filling',
      onSelect: () => setView('feature8')
    },
    {
      id: 'feature9',
      code: 'Module 09',
      icon: '🛰️',
      label: 'District Command Center',
      description: 'Pan-India surveillance, shortage forecasts & outbreak warnings',
      onSelect: () => setView('feature9')
    },
    {
      id: 'feature10',
      code: 'Module 10',
      icon: '🤖',
      label: 'Medical AI Assistant Agent',
      description: 'Autonomous action agent: booking, facility search, dosage reminders & voice',
      onSelect: () => setView('feature10')
    }
  ];

  const featureItems = actorRole === 'patient'
    ? allFeatureItems.filter(item => item.id !== 'feature9')
    : allFeatureItems;

  const isFeatureActive = currentView.startsWith('feature') || currentView === 'overview';

  return (
    <header className="sticky top-0 z-40 bg-white border-b border-slate-200 shadow-sm">
      {/* Main Navigation Bar */}
      <div className="max-w-7xl mx-auto px-4 sm:px-6 py-2.5 flex items-center justify-between flex-wrap gap-3">
        {/* Logo & Brand */}
        <div className="flex items-center gap-3 cursor-pointer select-none" onClick={() => setView('home')}>
          <MedVedaLogo className="h-10 w-10" />
          <div>
            <div className="flex items-center gap-2">
              <h1 className="font-black text-slate-900 text-lg tracking-tight flex items-center">
                <span>MED</span>
                <span className="text-teal-600 font-extrabold">VEDA</span>
              </h1>
            </div>
            <p className="text-[11px] text-slate-500 font-medium">Making quality healthcare accessible</p>
          </div>
        </div>

        {/* Navigation Tabs - Exactly 3 Sections: Home, Features (with Dropdown), About Us */}
        <nav className="flex items-center gap-1.5 bg-slate-100/90 p-1 rounded-xl border border-slate-200 text-xs font-semibold relative">
          {/* Section 1: Home */}
          <button
            type="button"
            onClick={() => {
              setView('home');
              setFeaturesOpen(false);
            }}
            className={`px-3.5 py-1.5 rounded-lg transition-all text-xs font-bold whitespace-nowrap ${currentView === 'home'
              ? 'bg-[#0b2b82] text-white shadow-sm'
              : 'text-slate-600 hover:text-[#0b2b82] hover:bg-blue-50/70'
              }`}
          >
            Home
          </button>

          {/* Section 2: Features (Clicking toggles dropdown showing all features) */}
          <div className="relative" ref={featuresRef}>
            <button
              type="button"
              onClick={() => setFeaturesOpen(!featuresOpen)}
              className={`px-3.5 py-1.5 rounded-lg transition-all text-xs font-bold whitespace-nowrap flex items-center gap-1.5 cursor-pointer ${isFeatureActive || featuresOpen
                ? 'bg-[#0b2b82] text-white shadow-sm'
                : 'text-slate-600 hover:text-[#0b2b82] hover:bg-blue-50/70'
                }`}
              aria-expanded={featuresOpen}
              aria-haspopup="true"
              aria-label="Features Menu"
              title="Browse all features"
            >
              <span>Features</span>
              <svg
                className={`w-3.5 h-3.5 transition-transform duration-200 ${featuresOpen ? 'rotate-180' : ''}`}
                fill="none"
                viewBox="0 0 24 24"
                stroke="currentColor"
              >
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" d="M19 9l-7 7-7-7" />
              </svg>
            </button>

            {/* Dropdown Menu with all Feature Map options */}
            {featuresOpen && (
              <div className="absolute top-full left-0 sm:left-1/2 sm:-translate-x-1/2 mt-2 w-80 sm:w-96 bg-white rounded-xl shadow-md border border-slate-200 p-2 z-50">
                <div className="px-3 py-2 border-b border-slate-100 flex items-center justify-between mb-1">
                  <span className="text-[11px] font-bold uppercase tracking-wider text-slate-500">
                    Platform Workspaces
                  </span>
                  <span className="text-[11px] text-slate-400 font-medium">
                    {featureItems.length} Available
                  </span>
                </div>

                <div className="space-y-1 max-h-[70vh] overflow-y-auto">
                  {featureItems.map((item) => {
                    const isActive = currentView === item.id;
                    return (
                      <button
                        key={item.id}
                        type="button"
                        onClick={() => {
                          item.onSelect();
                          setFeaturesOpen(false);
                        }}
                        title={`${item.code}: ${item.label}  -  ${item.description}`}
                        className={`w-full text-left p-2.5 rounded-lg transition-all flex items-start gap-3 group ${isActive
                          ? 'bg-slate-100 text-[#0b2b82]'
                          : 'hover:bg-slate-50 text-slate-800'
                          }`}
                      >
                        <div
                          className={`w-8 h-8 rounded-lg flex items-center justify-center shrink-0 ${isActive ? 'bg-[#0b2b82] text-white' : 'bg-slate-100 text-slate-700 group-hover:bg-blue-50 group-hover:text-[#0b2b82]'
                            }`}
                        >
                          <ModuleIcon id={item.id} className="w-4 h-4" />
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center justify-between gap-1">
                            <span className="text-xs font-bold leading-tight group-hover:text-[#0b2b82]">
                              {item.label}
                            </span>
                          </div>
                          <p className="text-[11px] text-slate-500 leading-snug font-normal mt-0.5 line-clamp-1">
                            {item.description}
                          </p>
                        </div>
                      </button>
                    );
                  })}
                </div>
              </div>
            )}
          </div>

          {/* Section 3: About Us */}
          <button
            type="button"
            onClick={() => {
              setView('about');
              setFeaturesOpen(false);
            }}
            className={`px-3.5 py-1.5 rounded-lg transition-all text-xs font-bold whitespace-nowrap ${currentView === 'about'
              ? 'bg-[#0b2b82] text-white shadow-sm'
              : 'text-slate-600 hover:text-[#0b2b82] hover:bg-blue-50/70'
              }`}
          >
            About Us
          </button>
        </nav>

        {/* Right Controls: Auth (Login / Sign Up) */}
        <div className="flex items-center gap-2.5 flex-wrap">
          {/* Login & Sign Up Option Buttons / User Profile Chip */}
          {currentUser ? (
            <div className="flex items-center gap-2 bg-blue-50/80 border border-blue-200/80 rounded-xl px-2.5 py-1 shadow-xs">
              <div className="w-6 h-6 rounded-full bg-[#0b2b82] text-white text-[11px] font-black flex items-center justify-center">
                {currentUser.name.charAt(0)}
              </div>
              <div className="flex flex-col text-left">
                <span className="text-[11px] font-extrabold text-slate-900 leading-none truncate max-w-[110px] sm:max-w-[140px]">
                  {currentUser.name}
                </span>
                <span className="text-[9px] text-[#0b2b82] font-bold uppercase leading-tight mt-0.5">
                  {currentUser.roleLabel || getRoleBadgeLabel(actorRole)}
                </span>
              </div>

              {currentUser.role === 'patient' && (
                <button
                  type="button"
                  onClick={() => {
                    const nextRole = actorRole === 'patient' ? 'doctor' : 'patient';
                    setActorRole(nextRole);
                  }}
                  className={`text-[10px] font-bold px-2 py-0.5 rounded-lg border transition-all cursor-pointer flex items-center gap-1 ${
                    actorRole === 'patient'
                      ? 'bg-white border-blue-200 text-[#0b2b82] hover:bg-blue-100 shadow-2xs'
                      : 'bg-[#0b2b82] text-white border-[#0b2b82] shadow-2xs'
                  }`}
                  title={actorRole === 'patient' ? "Preview Doctor's Clinical View" : "Return to Patient View"}
                >
                  <span className="flex items-center gap-1"><svg className="w-3 h-3 shrink-0" viewBox="0 0 20 20" fill="currentColor"><path d="M10 12a2 2 0 100-4 2 2 0 000 4z"/><path fillRule="evenodd" d="M.458 10C1.732 5.943 5.522 3 10 3s8.268 2.943 9.542 7c-1.274 4.057-5.064 7-9.542 7S1.732 14.057.458 10zM14 10a4 4 0 11-8 0 4 4 0 018 0z" clipRule="evenodd"/></svg><span>{actorRole === 'patient' ? "Doctor View" : "Patient View"}</span></span>
                </button>
              )}

              <button
                type="button"
                onClick={() => setCurrentUser(null)}
                className="text-[10px] font-bold text-slate-400 hover:text-critical-600 ml-1 px-1 py-0.5 rounded hover:bg-white transition-colors cursor-pointer"
                title="Log out"
              >
                Log Out
              </button>
            </div>
          ) : (
            <div className="flex items-center gap-1.5">
              <button
                type="button"
                onClick={() => {
                  setView('login');
                }}
                className="px-3 py-1.5 text-xs font-bold text-[#0b2b82] hover:bg-blue-50 rounded-lg transition-all border border-blue-200/80 cursor-pointer"
              >
                Log In
              </button>

              <button
                type="button"
                onClick={() => {
                  setAuthTab('signup');
                  setAuthModalOpen(true);
                }}
                className="px-3.5 py-1.5 text-xs font-bold bg-[#0b2b82] hover:bg-[#061d5c] text-white rounded-lg shadow-xs transition-all flex items-center gap-1 cursor-pointer"
              >
                <span>Sign Up</span>
              </button>
            </div>
          )}
        </div>
      </div>

      {/* Feature 01 Stepper Banner (shown when in Feature 01) */}
      {currentView === 'feature1' && (
        <WorkflowStepper currentScreen={currentScreen} setScreen={setScreen} maxClearedStep={maxClearedStep} />
      )}

      {/* MedVeda Authentication Modal (Log In / Sign Up) */}
      {authModalOpen && (
        <AuthModal
          initialTab={authTab}
          onClose={() => setAuthModalOpen(false)}
          onAuthSuccess={(user) => {
            setCurrentUser(user);
            setActorRole(user.role);
            setAuthModalOpen(false);
            setView('overview');
          }}
        />
      )}
    </header>
  );
}

function WorkflowStepper({ currentScreen, setScreen, maxClearedStep = 1 }) {
  return (
    <div className="w-full bg-white border-b border-slate-200 py-3 px-3 sm:px-6 shadow-2xs overflow-x-auto">
      <div className="max-w-5xl mx-auto flex items-center justify-between min-w-[760px] relative">
        {/* Background Track Line */}
        <div className="absolute top-4 left-6 right-6 h-0.5 bg-slate-200 -z-0"></div>

        {/* Active Progress Track Line */}
        <div
          className="absolute top-4 left-6 h-0.5 bg-[#0b2b82] transition-all duration-300 -z-0"
          style={{ width: `${((Math.min(currentScreen, STEPS.length) - 1) / (STEPS.length - 1)) * 95}%` }}
        ></div>

        {STEPS.map((step) => {
          const isDone = step.id < currentScreen;
          const isActive = step.id === currentScreen;
          const isUnlocked = step.id <= maxClearedStep;

          return (
            <div
              key={step.id}
              onClick={() => {
                if (isUnlocked) {
                  if (step.id === 4 && maxClearedStep >= 5) {
                    setScreen(5);
                  } else {
                    setScreen(step.id);
                  }
                }
              }}
              title={
                isUnlocked
                  ? `Go to Step ${step.id}: ${step.name}`
                  : `Step ${step.id} locked: Complete step ${step.id - 1} first`
              }
              className={`flex flex-col items-center z-10 transition-all ${
                isUnlocked ? 'cursor-pointer group' : 'cursor-not-allowed opacity-45 select-none'
              }`}
              style={{ width: '80px' }}
            >
              {/* Node Circle */}
              <div
                className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-xs transition-all ${
                  isActive
                    ? 'ring-4 ring-blue-100 bg-white border-2 border-[#0b2b82] text-[#0b2b82] shadow-sm transform scale-105'
                    : isDone
                    ? 'bg-[#0b2b82] border-2 border-[#0b2b82] text-white shadow-2xs'
                    : isUnlocked
                    ? 'bg-white border-2 border-slate-300 text-slate-500 group-hover:border-slate-400'
                    : 'bg-slate-100 border-2 border-slate-200 text-slate-400'
                }`}
              >
                {isActive ? (
                  <div className="w-2.5 h-2.5 rounded-full bg-[#0b2b82]"></div>
                ) : isDone ? (
                  <svg className="w-3.5 h-3.5" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                  </svg>
                ) : !isUnlocked ? (
                  <svg className="w-3 h-3 text-slate-400" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M5 9V7a5 5 0 0110 0v2a2 2 0 012 2v5a2 2 0 01-2 2H5a2 2 0 01-2-2v-5a2 2 0 012-2zm8-2v2H7V7a3 3 0 016 0z" clipRule="evenodd" />
                  </svg>
                ) : (
                  <span>{step.id}</span>
                )}
              </div>

              {/* Step Label */}
              <span
                className={`mt-1.5 text-[11px] text-center leading-tight font-bold transition-colors ${
                  isActive
                    ? 'text-[#0b2b82] font-extrabold'
                    : isDone
                    ? 'text-slate-800'
                    : isUnlocked
                    ? 'text-slate-500 group-hover:text-slate-700'
                    : 'text-slate-400'
                }`}
              >
                {step.name}
              </span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function StepperHeader({ currentStep, title, subtitle }) {
  const stepInfo = STEPS.find((s) => s.id === currentStep);
  const percent = Math.round((currentStep / STEPS.length) * 100);

  return (
    <div className="mb-6 pb-4 border-b border-slate-100">
      <div className="flex items-center justify-between text-xs font-bold text-slate-500 mb-1">
        <span className="text-brand-700 uppercase tracking-wide flex items-center gap-1.5">
          <span className="w-2 h-2 rounded-full bg-brand-600"></span>
          Step {currentStep}: {stepInfo?.name}
        </span>
        <span className="text-slate-400">{percent}% Completed</span>
      </div>
      <h2 className="text-xl sm:text-2xl font-black text-slate-900 tracking-tight">{title}</h2>
      {subtitle && <p className="text-xs sm:text-sm text-slate-500 mt-1 font-medium">{subtitle}</p>}
    </div>
  );
}

function VerificationBadge({ status }) {
  if (status === 'verified') {
    return (
      <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-bold bg-emerald-50 text-emerald-800 border border-emerald-300">
        <svg className="w-3.5 h-3.5 text-emerald-600 shrink-0" viewBox="0 0 20 20" fill="currentColor">
          <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
        </svg>
        <span>Verified Source</span>
      </span>
    );
  }
  return (
    <span className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-bold bg-amber-50 text-amber-800 border border-amber-300">
      <svg className="w-3.5 h-3.5 text-amber-600 shrink-0" viewBox="0 0 20 20" fill="currentColor">
        <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
      </svg>
      <span>Partially Verified</span>
    </span>
  );
}

function EmergencyPill({ specialtyMode, specialtyName = 'Specialty', emergencySpecialtyVerified }) {
  if (specialtyMode === 'EMERGENCY_AND_OPD' && emergencySpecialtyVerified) {
    return (
      <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-lg text-xs font-extrabold bg-emerald-50 text-emerald-800 border border-emerald-300">
        <svg className="w-3.5 h-3.5 text-emerald-600 shrink-0" viewBox="0 0 20 20" fill="currentColor">
          <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
        </svg>
        <span>24x7 Emergency {specialtyName} Available</span>
      </span>
    );
  }
  return (
    <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-lg text-xs font-bold bg-amber-50 text-amber-800 border border-amber-300">
      <svg className="w-3.5 h-3.5 text-amber-600 shrink-0" viewBox="0 0 20 20" fill="currentColor">
        <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm1-12a1 1 0 10-2 0v4a1 1 0 00.293.707l2.828 2.829a1 1 0 101.415-1.415L11 9.586V6z" clipRule="evenodd" />
      </svg>
      <span>{specialtyName} OPD Clinic Only (Not 24x7 Emergency)</span>
    </span>
  );
}

function VitalsConfidenceBadge({ source }) {
  if (source === 'worker_verified') {
    return (
      <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-[11px] font-bold bg-emerald-50 text-emerald-800 border border-emerald-200">
        <svg className="w-3 h-3 text-emerald-600 shrink-0" viewBox="0 0 20 20" fill="currentColor">
          <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
        </svg>
        <span>Worker Verified</span>
        <span className="text-[9px] opacity-75">(High Clinical Confidence)</span>
      </span>
    );
  }
  if (source === 'self_reported') {
    return (
      <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-[11px] font-bold bg-amber-50 text-amber-800 border border-amber-200">
        <svg className="w-3 h-3 text-amber-600 shrink-0" viewBox="0 0 20 20" fill="currentColor">
          <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
        </svg>
        <span>Self Reported</span>
        <span className="text-[9px] opacity-75">(Layperson Confidence)</span>
      </span>
    );
  }
  return (
    <span className="inline-flex items-center gap-1.5 px-2 py-0.5 rounded-md text-[11px] font-bold bg-blue-50 text-[#0b2b82] border border-blue-200">
      <svg className="w-3 h-3 text-[#0b2b82] shrink-0" viewBox="0 0 20 20" fill="currentColor">
        <path fillRule="evenodd" d="M10 9a3 3 0 100-6 3 3 0 000 6zm-7 9a7 7 0 1114 0H3z" clipRule="evenodd" />
      </svg>
      <span>Doctor Recorded</span>
    </span>
  );
}

